from dataclasses import dataclass


@dataclass(frozen=True)
class Lit:
    n: int


@dataclass(frozen=True)
class Var:
    name: str


@dataclass(frozen=True)
class Add:
    a: "E"
    b: "E"


@dataclass(frozen=True)
class Mul:
    a: "E"
    b: "E"


E = Lit | Var | Add | Mul


def emit(e: E) -> tuple[list[str], str]:
    """Return (lines, result).
